The partial fraction decomposition of
\[\frac{x^2 - 19}{x^3 - 2x^2 - 5x + 6}\]is
\[\frac{A}{x - 1} + \frac{B}{x + 2} + \frac{C}{x - 3}.\]Find the product $ABC.$

Put your final answer within \boxed{}.
#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

int main() {
// Define the polynomial
vector<double> polynomial = {1, -2, -5, 6};

// Find the roots of the polynomial
vector<double> roots;
for (int i = 0; i < polynomial.size(); i++) {
if (polynomial[i] == 0) {
roots.push_back(0);
} else {
roots.push_back(-polynomial[i] / polynomial[i + 1]);
}
}

// Find the partial fraction decomposition
vector<double> partial_fractions;
for (int i = 0; i < roots.size(); i++) {
partial_fractions.push_back(1 / (roots[i] - 1));
}

// Find the product of the partial fractions
double product = 1;
for (int i = 0; i < partial_fractions.size(); i++) {
product *= partial_fractions[i];
}

// Print the product
cout << "The product of the partial fractions is: " << product << endl;

return 0;
}

